insert into questions (question_id, stage_id, chapter_id, type, prompt, code, answer, explanation, hint, xp, "order", active) values ('Q000155', 'STG001', 'CH0031', 'MCQ', 'What happens during the execution stage?', '', 'The program is run and produces output', '', 'This is the stage where you finally run the program.', 1, 5, true);
insert into questions (question_id, stage_id, chapter_id, type, prompt, code, answer, explanation, hint, xp, "order", active) values ('Q000156', 'STG001', 'CH0032', 'MCQ', 'Your first output — which function displays something on the screen?', '', 'printf()', '', 'Think about the function that is used to show something on the screen.', 1, 1, true);
insert into questions (question_id, stage_id, chapter_id, type, prompt, code, answer, explanation, hint, xp, "order", active) values ('Q000157', 'STG001', 'CH0032', 'MCQ', 'Build on Q1 — which line correctly prints "Welcome to C"?', '', 'printf("Welcome to C");', '', 'Text that we want to display should be written inside double quotation marks.', 1, 2, true);
insert into questions (question_id, stage_id, chapter_id, type, prompt, code, answer, explanation, hint, xp, "order", active) values ('Q000158', 'STG001', 'CH0032', 'MCQ', 'Build the complete program — which option is a correctly structured C program?', '', 'int main() {
