insert into questions (question_id, stage_id, chapter_id, type, prompt, code, answer, explanation, hint, xp, "order", active) values ('Q000159', 'STG001', 'CH0032', 'MCQ', 'Previous chapter recap: which function acts as the starting point of a C program''s structure?', '', 'main()', '', 'Think about the function that acts as the starting point of a C program.', 1, 4, true);
insert into questions (question_id, stage_id, chapter_id, type, prompt, code, answer, explanation, hint, xp, "order", active) values ('Q000160', 'STG001', 'CH0032', 'MCQ', 'Previous chapter recap: what does the ; symbol mean in C syntax?', '', 'End of the statement', '', 'Look at the symbol ; — it tells C that a statement has ended.', 1, 5, true);
insert into questions (question_id, stage_id, chapter_id, type, prompt, code, answer, explanation, hint, xp, "order", active) values ('Q000161', 'STG001', 'CH0033', 'MCQ', 'What is a comment in C programming?', '', 'A note written for programmers', '', 'Think of a comment as a small note that helps people understand the code.', 1, 1, true);
insert into questions (question_id, stage_id, chapter_id, type, prompt, code, answer, explanation, hint, xp, "order", active) values ('Q000162', 'STG001', 'CH0033', 'MCQ', 'Which symbol is used for a single-line comment?', '', '//', '', 'Look for the symbol that uses two forward slashes.', 1, 2, true);
insert into questions (question_id, stage_id, chapter_id, type, prompt, code, answer, explanation, hint, xp, "order", active) values ('Q000163', 'STG001', 'CH0033', 'MCQ', 'Which symbols are used for a multi-line comment?', '', '/* */', '', 'This comment starts with /* and ends with */.', 1, 3, true);
insert into questions (question_id, stage_id, chapter_id, type, prompt, code, answer, explanation, hint, xp, "order", active) values ('Q000164', 'STG001', 'CH0033', 'MCQ', 'Will C execute the statements written inside a comment?', '', 'No', '', 'Comments are only notes for humans. The C program ignores them.', 1, 4, true);
insert into questions (question_id, stage_id, chapter_id, type, prompt, code, answer, explanation, hint, xp, "order", active) values ('Q000165', 'STG001', 'CH0033', 'MCQ', 'Why are comments used in a C program?', '', 'To help programmers understand the code', '', 'Comments make the code easier for programmers to read and understand.', 1, 5, true);
insert into questions (question_id, stage_id, chapter_id, type, prompt, code, answer, explanation, hint, xp, "order", active) values ('Q000166', 'STG001', 'CH0034', 'MCQ', 'What is a variable in C?', '', 'A named storage box for a value', '', 'Think of a variable as a box with a name that can hold some information.', 1, 1, true);
insert into questions (question_id, stage_id, chapter_id, type, prompt, code, answer, explanation, hint, xp, "order", active) values ('Q000167', 'STG001', 'CH0034', 'MCQ', 'Which of the following is a correct way to create an integer variable?', '', 'int age;', '', 'The data type comes before the variable name.', 1, 2, true);
insert into questions (question_id, stage_id, chapter_id, type, prompt, code, answer, explanation, hint, xp, "order", active) values ('Q000168', 'STG001', 'CH0034', 'PREDICT_OUTPUT', 'What does this statement do?', 'int age = 18;', 'Creates age and stores 18 in it', '', 'Look at the = symbol. It puts the value 18 inside the variable age.', 1, 3, true);
insert into questions (question_id, stage_id, chapter_id, type, prompt, code, answer, explanation, hint, xp, "order", active) values ('Q000169', 'STG001', 'CH0034', 'MCQ', 'What is the purpose of the = symbol in a variable statement?', '', 'To assign/store a value', '', 'Think of = as putting a value into the variable.', 1, 4, true);
