insert into questions (question_id, stage_id, chapter_id, type, prompt, code, answer, explanation, hint, xp, "order", active) values ('Q000181', 'STG001', 'CH0035', 'TYPE_CODE', '[INTERMEDIATE] Student Details Using Comments

