}', '', 'Look carefully at the variable statements. Also remember how a char value is written.', 1, 12, true);
insert into questions (question_id, stage_id, chapter_id, type, prompt, code, answer, explanation, hint, xp, "order", active) values ('Q000183', 'STG001', 'CH0035', 'TYPE_CODE', '[HARD] Student Report

Write a C program to display:
===== STUDENT REPORT =====
Initial: S
Age: 18
Maths: 85
Science: 90
English: 88
==========================

Rules:
- Use char for initial.
- Use int for age and marks.
- Add comments.
- Use printf() for the output.', 'Expected Output:
===== STUDENT REPORT =====
Initial: S
Age: 18
Maths: 85
Science: 90
English: 88
==========================', '#include <stdio.h>

int main()
{

   // Store student details
   char initial = ''S'';
   int age = 18;

   // Store subject marks
   int maths = 85;
   int science = 90;
   int english = 88;

   printf("===== STUDENT REPORT =====\n");
   printf("Initial: %c\n", initial);
   printf("Age: %d\n", age);
   printf("Maths: %d\n", maths);
   printf("Science: %d\n", science);
   printf("English: %d\n", english);

   printf("==========================");

   return 0;

}', '', 'Create five variables first. Then use printf() to display each variable.', 1, 13, true);
insert into questions (question_id, stage_id, chapter_id, type, prompt, code, answer, explanation, hint, xp, "order", active) values ('Q000184', 'STG001', 'CH0035', 'TYPE_CODE', '[HARD] Personal Information Program

