insert into questions (question_id, stage_id, chapter_id, type, prompt, code, answer, explanation, hint, xp, "order", active) values ('Q000185', 'STG001', 'CH0035', 'TYPE_CODE', '[HARD] Build a Complete C Program

Write a complete C program that displays:
STUDENT PROFILE
Initial: S
Age: 18
Marks: 92
Percentage: 92.5
Grade: A

Requirements:
1. Use char for initial.
2. Use int for age and marks.
3. Use float for percentage.
4. Create separate variables.
5. Add comments.
6. Use printf() to display the profile.
7. Follow the correct C program structure.', 'Expected Output:
************************
 STUDENT PROFILE
************************
Initial: S
Age: 18
Marks: 92
Percentage: 92.5
Grade: A
************************', '#include <stdio.h>

int main()
{

   // Store student profile
   char initial = ''S'';
   int age = 18;
   int marks = 92;
   float percentage = 92.5;
   char grade = ''A'';

   // Display student profile
   printf("************************\n");
   printf(" STUDENT PROFILE\n");
   printf("************************\n");
   printf("Initial: %c\n", initial);
   printf("Age: %d\n", age);
   printf("Marks: %d\n", marks);
   printf("Percentage: %.1f\n", percentage);
   printf("Grade: %c\n", grade);
   printf("************************");

   return 0;
}', '', 'Break the problem into small steps: Create variables → Store values → Use printf() → Format the output.', 1, 15, true);

