insert into test_hints (hint_id, question_id, hint_text, active, "order") values ('H_Q000151', 'Q000151', 'Think about what C is used for — it is used to create programs.', true, 1);
insert into test_hints (hint_id, question_id, hint_text, active, "order") values ('H_Q000152', 'Q000152', 'Before a computer can run a program, we need to write the code.', true, 1);
