-- deactivate
-- Soft-remove the old Stage 0 ("Constants, Variables and Data Types") from the active
-- learning path. Data is preserved (active=false), not deleted, per project convention.
update stages set active = false where stage_id = 'STG000';
update chapters set active = false where stage_id = 'STG000';
update learn_content set active = false where stage_id = 'STG000';
update questions set active = false where stage_id = 'STG000';
update options set active = false where question_id in (select question_id from questions where stage_id = 'STG000');
update test_hints set active = false where question_id in (select question_id from questions where stage_id = 'STG000');
update question_terms set active = false where question_id in (select question_id from questions where stage_id = 'STG000');

-- prerequisites
-- P001 (first Practice Bank challenge) previously required completing the old STG000.
-- Since STG000 is now deactivated (see above), bootstrap()'s active-stage list will
-- never contain it again, so stageCompleteIds could never include it -- Practice Bank
-- would stay permanently locked. Repoint the same rule at the new Stage 0 (STG001) so
-- completing the new Foundations chapters continues to unlock Practice, as intended.
update prerequisites set prerequisite_id = 'STG001' where target_id = 'P001' and prerequisite_id = 'STG000';
